/* Host test for syscfgvalid.c. Fixtures are generated by gen_fixtures.py.
 * Build: cc -std=c99 -Wall -Wextra -I.. test_syscfgvalid.c ../syscfgvalid.c -o t && ./t fixtures
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "syscfgvalid.h"

static int fails;

static size_t readf(const char *dir, const char *name, uint8_t *buf, size_t max)
{
    char path[512];
    snprintf(path, sizeof path, "%s/%s", dir, name);
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "missing %s\n", path); exit(2); }
    size_t n = fread(buf, 1, max, f);
    fclose(f);
    return n;
}

/* Each case dir holds sector.bin (4096), target.bin, flash.req, expect.txt ("WRITE"/"NOOP"/"REFUSE"). */
static void run_case(const char *root, const char *name)
{
    char dir[512];
    uint8_t sector[SCV_SECTOR_SIZE], target[512], req[128], exp[32] = {0};
    uint32_t cur, nw;
    char why[96];

    snprintf(dir, sizeof dir, "%s/%s", root, name);
    if (readf(dir, "sector.bin", sector, sizeof sector) != SCV_SECTOR_SIZE) { fprintf(stderr, "bad sector %s\n", name); exit(2); }
    size_t tlen = readf(dir, "target.bin", target, sizeof target);
    size_t rlen = readf(dir, "flash.req", req, sizeof req);
    readf(dir, "expect.txt", exp, sizeof exp - 1);
    exp[strcspn((char *)exp, "\r\n")] = 0;

    const char *got;
    if (scv_parse_req((const char *)req, rlen, &cur, &nw) != 0) {
        got = "REFUSE";
        strcpy(why, "flash.req unparsable");
    } else {
        enum scv_result r = scv_validate(sector, target, tlen, cur, nw, why, sizeof why);
        got = r == SCV_WRITE ? "WRITE" : r == SCV_NOOP ? "NOOP" : "REFUSE";
    }
    int ok = strcmp(got, (char *)exp) == 0;
    if (!ok) fails++;
    printf("%-4s %-28s expect=%-6s got=%-6s (%s)\n", ok ? "ok" : "FAIL", name, (char *)exp, got, why);
}

int main(int argc, char **argv)
{
    if (argc < 3) { fprintf(stderr, "usage: t <fixtures-dir> <case>...\n"); return 2; }
    /* crc32 known-answer: "123456789" -> CBF43926 */
    if (scv_crc32((const uint8_t *)"123456789", 9) != 0xCBF43926u) { printf("FAIL crc32 KAT\n"); fails++; }
    for (int i = 2; i < argc; i++)
        run_case(argv[1], argv[i]);
    printf("%s (%d failures)\n", fails ? "FAILED" : "PASSED", fails);
    return fails != 0;
}
